def circum(a,b,c):
    m,n=mid(a,b),mid(a,c)
    return intersect(m,(m[0]+a[1]-b[1],m[1]+b[0]-a[0]),n,(n[0]+a[1]-c[1],n[1]+c[0]-a[0]))


def chord(center,point,unit):
    t=2*sum((center[i]-point[i])*unit[i] for i in [0,1])/sum(v*v for v in unit)
    return tuple(point[i]+t*unit[i] for i in [0,1])


def reflect(p,m):
    return tuple(2*b-a for a,b in zip(p,m))


def direction(deg):
    return(cos(deg*pi/180),sin(deg*pi/180))


